#!/usr/bin/env bash
set -euo pipefail

regions=(AFR EAS ECA LAC NAC SAS OCE)
declare -A ind
ind[GDP]=NY.GDP.MKTP.CD
ind[Population]=SP.POP.TOTL
year=2022
base="http://api.worldbank.org/v2/region/%s/indicator/%s?date=${year}&format=json"

declare -A result

for r in "${regions[@]}"; do
  for key in "${!ind[@]}"; do
    url=$(printf "$base" "$r" "${ind[$key]}")
    # Grab the second element of the outer array, first element of inner array, then .value
    val=$(curl -s "$url" | jq -r '.[1][0].value // empty')
    # jq prints `null` as a literal string; we want true JSON null, so keep empty string as null
    if [[ -z "$val" ]]; then
