const https = require('https');

const regions = ['AFR', 'EAS', 'ECA', 'LAC', 'NAC', 'SAS', 'OCE'];
const indicators = {
  GDP: 'NY.GDP.MKTP.CD',
  Population: 'SP.POP.TOTL',
};
const year = 2022;
const base = 'http://api.worldbank.org/v2/region/{region}/indicator/{indicator}?date=' + year + '&format=json';

function fetchValue(region, indicator) {
  const url = base
    .replace('{region}', region)
    .replace('{indicator}', indicator);
  return new Promise((resolve, reject) => {
    https.get(url, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          const value = json[1] && json[1][0] ? json[1][0].value : null;
          resolve(value);
        } catch (e) {
          reject(e);
        }
      });
    }).on('error', reject);
  });
}

(async () => {
  const result = {};
  for (const r of regions) {
    result[r] = {};
    for (const [key, ind] of Object.entries(indicators)) {
      try {
        const val = await fetchValue(r, ind);
        result[r][key] = val === undefined ? null : val;
      } catch (e) {
        console.error(`Error fetching ${r}/${key}:`, e);
        result[r][key] = null;
      }
    }
  }
  console.log(JSON.stringify(result, null, 2));
})();
